/*
 * Verified substitutions: KiCad (footprint,rotation) -> EasyEDA Pro
 * system-library footprint.
 *
 * Generated by matching every docType=4 entry in the bundled
 * easyeda-std.elib against the extracted KiCad pad sets (pad count,
 * relative pad positions under a 90-degree-stepped rotation plus
 * translation, pad numbers, drill vs hole sizes).
 *
 *   sysFpUuid / sysFpName  — system-library footprint (read-only lib,
 *                            uuid from lib_LibrariesList.getSystemLibraryUuid)
 *   rot                    — EasyEDA rotation (deg, CCW+, +Y-up frame) to
 *                            apply at placement so system pads land on the
 *                            KiCad pad positions
 *   dx, dy                 — origin offset (mil, same frame): system
 *                            footprints anchor differently than KiCad ones,
 *                            so placement = plan position + (dx, dy)
 *   padmap                 — KiCad pad number -> system pad number.
 *                            Identity for every match except the K1 relay:
 *                            hf3ff numbers the coil pads swapped.  Symbol
 *                            pins are generated with the SYSTEM numbers so
 *                            pin->pad import maps to the right copper.
 *   worst                  — worst pad-position error of the fit (mil)
 *
 * The five (footprint,rotation) keys NOT listed have no acceptable system
 * match and stay custom-drawn: XT60 (no XT60 in the bundled lib), the
 * mini blade-fuse direct-solder pads (no blade-fuse footprint), the
 * 1x22 single-row header (only a 2x11 dual-row exists), the DO-41/SOD81
 * diode (only capacitor footprints share its pitch), and the 1.5 mm /
 * 0.7 mm test point (system test points are 2.5 mm+).
 */

export interface SysFpMatch {
	sysFpUuid: string;
	sysFpName: string;
	rot: number;
	dx: number;
	dy: number;
	padmap: Record<string, string>;
	worst: number;
}

