/* Keys deliberately left to the custom-draw path (with reason). */
export const CUSTOM_KEYS: Record<string, string> = {
	'AMASS_XT60-M_1x02_P7.20mm_Vertical@0': 'no XT60 footprint in bundled library',
	'Fuse_Blade_Mini_directSolder@90': 'no blade-fuse footprint in bundled library',
	'PinHeader_1x22_P2.54mm_Vertical@90': 'only a 2x11 dual-row header exists',
	'D_DO-41_SOD81_P10.16mm_Horizontal@0': 'no DO-41-class diode at P10.16mm — keep KiCad geometry/silk',
	'TestPoint_THTPad_D1.5mm_Drill0.7mm@0': 'system test points are >=2.5mm pad / >=1.4mm hole',
};

/** Normalize the board-data fpKey ('<footprint>@<rot>' where rot may be
 *  '0.0', '90.0', ...) to the lookup form used above ('0'|'90'|...). */
export function fpKeyOf(footprint: string, rot: number): string {
	return `${footprint}@${Math.round(rot * 10) % 3600 / 10}`;
}
